mapper.update:
UPDATE user_tokens SET
  last_connection_date = #{lastConnectionDate, jdbcType=BIGINT}
WHERE
  user_uuid = #{userUuid, jdbcType=VARCHAR}
  AND name = #{name, jdbcType=VARCHAR}

mapper.select:
SELECT t.user_uuid as "userUuid", count(t.name) as "tokenCount" FROM user_tokens t WHERE t.user_uuid in
#{userUuid, jdbcType=VARCHAR}
GROUP BY t.user_uuid

mapper.sql:
FROM user_tokens t INNER JOIN users u ON u.uuid = t.user_uuid INNER JOIN organization_members om ON om.user_uuid = t.user_uuid AND om.organization_uuid = #{organizationUuid, jdbcType=VARCHAR} LEFT JOIN projects p ON t.project_uuid = p.uuid WHERE (t.project_uuid IS NULL OR p.organization_uuid = #{organizationUuid, jdbcType=VARCHAR})
AND ( lower(u.login) LIKE #{searchText, jdbcType=VARCHAR} ESCAPE '/' OR lower(u.name) LIKE #{searchText, jdbcType=VARCHAR} ESCAPE '/' OR lower(t.name) LIKE #{searchText, jdbcType=VARCHAR} ESCAPE '/' )
AND t.created_at < #{createdBefore, jdbcType=BIGINT}
